INSERT INTO FactCashBalances (SK_CustomerID, SK_AccountID, SK_DateID, BatchID, Cash) SELECT DA.SK_CustomerID AS SK_CustomerID, DA.SK_AccountID AS SK_AccountID, DD.SK_DateID AS SK_DateID, 1 AS BatchID, SUM(SUM(CT.CT_AMT)) OVER (PARTITION BY DA.AccountID ORDER BY CAST(CT.CT_DTS AS DATE) ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS Cash FROM Source.CashTransaction AS CT INNER JOIN DimAccount AS DA ON CT.CT_CA_ID = DA.AccountID AND DA.EffectiveDate <= CAST(CT.CT_DTS AS DATE) AND CAST(CT.CT_DTS AS DATE) < DA.EndDate INNER JOIN DimDate AS DD ON CAST(CT.CT_DTS AS DATE) = DD.DateValue GROUP BY DA.AccountID, DA.SK_CustomerID, DA.SK_AccountID, DD.SK_DateID, CAST(CT.CT_DTS AS DATE)